INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1405, 6, 'A015000', 'n mixta de cultivos y animales sin especialización en ninguna de las actividades. El tamaño del conjunto de la explotación agrícola no es un factor determinante. Si el cultivo de productos agrícolas o la cría de animales representan en una unidad determinada una proporción igual o superior al 66% de los márgenes brutos corrientes, la actividad mixta no debe clasificarse en esta clase, sino entre los cultivos o las actividades de cría de animales.', 801, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1406, 6, 'A016101', 'Actividades de acondicionamiento y mantenimiento de terrenos para usos agrícolas: plantación o siembra de cultivos y cosecha, poda de árboles frutales y viñas, transplante de arroz y entresacado de remolacha.', 802, true);
