INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1411, 6, 'A016202', 'Servicios de inspección sanitaria, arreo y pasturaje de ganado, capadura de animales, limpieza de gallineros, etcétera.', 803, true);
