INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1414, 6, 'A016309', 'Otras actividades de Poscosecha: desmotado de algodón, preparación de hojas de tabaco, preparación de cacao y café en grano, secado al sol de frutas y hortalizas.', 804, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1415, 6, 'A016400', ' eliminación de los materiales que no son semilla, semillas de tamaño inferior al normal, semillas dañadas mecánicamente o por insectos y semillas inmaduras, así como la eliminación de la humedad de las semillas hasta un nivel que permita su almacenamiento seguro. Esta actividad incluye el secado, limpieza, clasificación y tratamiento de semillas hasta su comercialización. Se incluye asi mismo el tratamiento de semillas genéticamente modificadas.', 805, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1416, 6, 'A017001', 'Actividades de caza ordinaria y mediante trampas para fines comerciales. Captura de animales (vivos o muertos) para carne, producción de pieles incluso pieles finas, cueros (cueros de reptiles), plumas para utilizarlos en la investigación, en zoológicos o como animales domésticos.', 806, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1417, 6, 'A017002', 'Captura en tierra de mamíferos marinos, como focas y morsas.', 806, true);
