INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1596, 6, 'C131202', 'Fabricación de tejidos (telas) aterciopelados y de felpilla, tejidos de rizo, tejidos de gasa, etcétera.', 864, true);
