INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1598, 6, 'C131204', 'Servicios de apoyo a la elaboración de tejidos a cambio de una retribución o por contrato.', 864, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1599, 6, 'C131209', 'Fabricación de otros tejidos (telas) anchos de lino, ramio, cáñamo, yute y fibras blandas y de hilados especiales, tejidos de fibra de carbono e hilos arámidos, tejidos que imitan las pieles finas, etcétera.', 864, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1600, 6, 'C131301', 'Servicio de blanqueo y teñido de fibras, hilados, tejidos (telas) y artículos textiles, incluido prendas de vestir: pantalones vaqueros (jeans) etcétera, realizado por terceros a cambio de una retribución o por contrato.', 865, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1601, 6, 'C131302', 'Servicio de apresto, calandrado, secado, vaporizado, encogimiento, perchado, remallado, sanforizado, mercerizado, plisado de textiles y artículos textiles, incluido prendas de vestir realizado por terceros a cambio de una retribución o por contrato.', 865, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1602, 6, 'C131303', 'Servicio de impermeabilizado, revestimiento, cauchutado o impregnación de prendas realizado por terceros a cambio de una retribución o por contrato.', 865, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1603, 6, 'C131304', 'Servicio de estampado serigráfico de productos textiles y prendas de vestir, realizado por terceros a cambio de una retribución o por contrato.', 865, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1604, 6, 'C139101', 'Fabricación de tejidos (telas) de punto o ganchillo: tejidos aterciopelados y de rizo, pieles de imitación de punto obtenidas mediante el tricotaje.', 866, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1605, 6, 'C139102', 'Servicios de apoyo a la fabricación de tejidos de punto y ganchillo a cambio de una retribución o por contrato.', 866, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1606, 6, 'C139201', 'Fabricación de artículos confeccionados con cualquier tipo de material textil, incluidos tejidos (telas) de punto y ganchillo: frazadas, mantas de viaje, sobrecamas, cobijas, edredones, ropa de cama, sábanas, mantelería, toallas y artículos de cocina acolchados, edredones, cojines, pufés, almohadas, sacos de dormir, artículos para el baño, etcétera, incluido  tejidos para mantas eléctricas.', 867, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1607, 6, 'C139202', 'Fabricación de accesorios confeccionados para el hogar: cortinas, cenefas, visillos.', 867, true);
