INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1609, 6, 'C139204', 'Fabricación de tapices tejidos a mano.', 867, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1610, 6, 'C139205', 'Fabricación de banderas, banderines, gallardetes, estandartes, etcétera.', 867, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1611, 6, 'C139206', 'Fabricación de fundas (forros) o cobertores de asientos para automóviles, fundas para maquinarias, muebles, neumáticos, etcétera.', 867, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1612, 6, 'C139207', 'Servicios de apoyo a la fabricación de artículos confeccionados de materiales textiles, excepto prendas de vestir a cambio de una retribución o por contrato.', 867, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1613, 6, 'C139209', 'Fabricación de otros artículos confeccionados con textiles: paños para desempolvar, paños de cocina y artículos similares, chalecos salvavidas, paracaídas, etcétera.', 867, true);
