INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1616, 6, 'C139303', 'Servicios de apoyo a la fabricación de tapices y alfombras a cambio de una retribución o por contrato.', 868, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1617, 6, 'C139401', 'Fabricación de cuerdas, cordeles, bramantes e hilos de fibras textiles o de cintas o similares, estén o no impregnados, revestidos, cubiertos o forrados con caucho o plástico.', 869, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1618, 6, 'C139402', 'Fabricación de mallas anudadas de cuerda, cordel o bramante: redes de pesca, defensas para bordos, cojines para descarga, eslingas, cuerdas y maromas con aros metálicos, etcétera, incluido fabricación de hamacas, bolsas de red para pelotas, redes para deportes, etcétera.', 869, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1619, 6, 'C139403', 'Servicios de apoyo a la fabricación de cuerdas, cordeles, bramantes y redes a cambio de una retribución o por contrato.', 869, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1620, 6, 'C139901', ' incluidos los de urdimbre sin trama sujetos por una sustancia adhesiva: marbetes, insignias, etcétera; artículos de pasamanería: cordones de materiales textiles para zapatos, trencillas, borlas, madroños, tules y otros tejidos (telas) de mallas anudadas, de encaje y bordados, en piezas, tiras o motivos decorativos, tejidos (telas) de red y del tipo que se utiliza para la confección de visillos tricotados en máquinas Raschel o máquinas similares.', 870, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1621, 6, 'C139902', 'Fabricación de tejidos (telas) impregnados, revestidos, recubiertos o laminados con plástico.', 870, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1622, 6, 'C139903', 'Fabricación de hilados metalizados e hilados entorchados; hilos y cuerdas de caucho revestidos de materiales textiles; hilados y bandas textiles recubiertos impregnados, revestidos o forrados con caucho o plástico.', 870, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1623, 6, 'C139904', 'Fabricación de tejidos de hilados de gran resistencia para cuerdas de neumáticos.', 870, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1624, 6, 'C139905', 'Fabricación de tejidos tratados o revestidos: papel tela, lienzos preparados para pintores, bocací y tejidos rígidos similares, tejidos revestidos con goma o sustancias amiláceas.', 870, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1625, 6, 'C139906', 'Fabricación de artículos textiles diversos: mechas de materiales textiles, camisas para mecheros de gas incandescentes y tejidos tubulares para su fabricación, mangueras, correas transportadoras y correaje de transmisión (estén reforzados o no con metales u otros materiales), tela para tamices, tela de filtración, fieltro, etcétera.', 870, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1626, 6, 'C139907', 'Servicios de apoyo a la fabricación de otros productos textiles n.c.p a cambio de una retribución o por contrato.', 870, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1627, 6, 'C139909', 'Fabricación de otros productos textiles: adornos para vehículos automotores, cinta-tejido sensible a la presión, etcétera.', 870, true);
