INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1630, 6, 'C141003', 'Fabricación de ropa interior y ropa de dormir de telas tejidas, de punto y ganchillo, de encaje, etcétera, para hombres, mujeres y niños: panties, calzoncillos, pijamas, camisones, batas, blusas, slips, sujetadores, fajas, etcétera.', 871, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1631, 6, 'C141004', 'Actividades de confección a la medida de prendas de vestir (costureras, sastres).', 871, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1632, 6, 'C141005', 'Fabricación de gorros y sombreros (incluido los de piel y paja toquilla).', 871, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1633, 6, 'C141006', 'Servicios de apoyo a la fabricación de prendas de vestir, excepto prendas de piel a cambio de una retribución o por contrato.', 871, true);
