INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1635, 6, 'C142001', 'Fabricación de artículos de piel (con pelo natural): prendas y accesorios de piel incluido los confeccionados con pieles “alargadas”, planchas, cuadrados, tiras, etcétera.', 872, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1636, 6, 'C142002', 'Fabricación de artículos diversos de piel (con pelo natural): alfombras, pufs sin relleno, paños para pulimento industrial.', 872, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1637, 6, 'C142003', 'Servicios de apoyo a la fabricación de artículos de piel a cambio de una retribución o por contrato.', 872, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1638, 6, 'C143001', 'Fabricación de artículos de confección de punto y ganchillo: jerseys, suéteres, chalecos, camisetas y artículos similares.', 873, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1639, 6, 'C143002', 'Fabricación de medias, incluidos calcetines, leotardos y pantimedias.', 873, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1640, 6, 'C143003', 'Servicios de apoyo a la fabricación de artículos de punto y ganchillo a cambio de una retribución o por contrato.', 873, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1641, 6, 'C151101', 'Actividades de descarnadura, tundido, depilado, engrase, curtido, blanqueo, teñido, adobo de pieles y cueros de pieles finas y cueros con pelo.', 874, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1642, 6, 'C151102', 'Fabricación de cueros regenerados (artificiales), cueros gamuzados y apergaminados, charol y cueros metalizados.', 874, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1643, 6, 'C151103', 'Servicios de apoyo al curtido y adobo de cueros; adobo y teñido de pieles a cambio de una retribución o por contrato.', 874, true);
