INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1645, 6, 'C151202', 'Fabricación de artículos de talabartería y guarnicionería: sillas de montar, arreos, látigos y fustas.', 875, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1646, 6, 'C151203', 'Servicios de apoyo a la fabricación de maletas, bolsos de mano y artículos similares, artículos de talabartería y guarnicionería a cambio de una retribución o por contrato.', 875, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1647, 6, 'C151209', 'Fabricación de otros artículos diversos de cuero o cuero regenerado: correas de transmisión, cordones de cuero para zapatos, correas no metálicas para relojes (de materiales textiles, cuero y plástico), artículos de envase o embalaje, artículos usados con fines técnicos, etcétera.', 875, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1648, 6, 'C152001', 'Fabricación de calzado, botines, polainas y artículos similares para todo uso, de cualquier material y mediante cualquier proceso, incluido el moldeado (aparado de calzado).', 876, true);
