INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1650, 6, 'C152003', 'Servicios de apoyo a la fabricación de calzado a cambio de una retribución o por contrato.', 876, true);
