INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1652, 6, 'C161002', 'Fabricación de tabletas para la ensambladura de pisos de madera (duela, media duela, parquet).', 877, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1653, 6, 'C161003', 'Servicios de apoyo al aserrado y acepilladura de madera a cambio de una retribución o por contrato.', 877, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1654, 6, 'C161009', 'Fabricación de otros tipos de madera en bruto: rodrigones, estacas, tablillas, traviesas de madera (durmientes) para vías férreas, etcétera.', 877, true);
