INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1656, 6, 'C162102', 'Servicios de apoyo a la fabricación de hojas de madera para enchapado y tableros a base de madera a cambio de una retribución o por contrato.', 878, true);
