INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1659, 6, 'C162203', 'Fabricación de casas móviles, edificios prefabricados y componentes de los mismos, predominantemente de madera, por ejemplo saunas.', 879, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1660, 6, 'C162204', 'Servicios de apoyo a la fabricación de partes y piezas de carpintería para edificios y construcciones a cambio de una retribución o por contrato.', 879, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1661, 6, 'C162301', 'Fabricación de cajas, cajones, barriles y envases similares, toneles, barricas, cubas, tinas y otros productos de tonelería de madera.', 880, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1662, 6, 'C162302', 'Fabricación de paletas, paletas-caja y otras bandejas de madera para operaciones de carga.', 880, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1663, 6, 'C162303', 'Fabricación de carretes de madera para cables.', 880, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1664, 6, 'C162304', 'Servicios de apoyo a la fabricación de recipientes de madera a cambio de una retribución o por contrato.', 880, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1665, 6, 'C162911', 'Fabricación de productos de madera: mangos y monturas de herramientas, cepillos y escobas.', 881, true);
