INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1671, 6, 'C162917', 'Fabricación de carretes, tapas, canillas de bobinas, carretes para hilos de coser y artículos similares de madera torneada.', 881, true);
