INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1676, 6, 'C162923', 'Fabricación de trenzas y artículos similares de materiales trenzables: esteras, esterillas, persianas, cajas, cestos y artículos de mimbre, etcétera.', 882, true);
