INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1680, 6, 'C170103', 'Fabricación de papel y cartón para su posterior elaboración industrial.', 884, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1681, 6, 'C170104', 'Tratamiento industrial posterior de papel y cartón: revestimiento, recubrimiento e impregnación de papel y cartón; papeles laminados, papel aluminio, papel Kraft, cartulina, papel multilaminar, papeles absorbentes, papel pergamino, papel cigarrillo, papel rizado o plegado, etcétera.', 884, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1682, 6, 'C170105', 'Fabricación de papel de periódico y otros papeles para imprimir y escribir.', 884, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1683, 6, 'C170106', 'Servicios de apoyo a la fabricación de pasta de madera, papel y cartón a cambio de una retribución o por contrato.', 884, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1684, 6, 'C170109', 'Elaboración de otros tipos de papel: papel carbón o papel esténcil en rollos u hojas grandes, papel hecho a mano, fabricación de guata de celulosa y tiras de fibras de celulosa etcétera.', 884, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1685, 6, 'C170201', 'Fabricación del papel y cartón ondulados o corrugado.', 885, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1686, 6, 'C170202', 'Fabricación de envases de papel o de cartón ondulado, rígido o plegable: cajas, cajones, estuches, envases, archivadores de cartón de oficina y artículos similares.', 885, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1687, 6, 'C170203', 'Fabricación de sacos y de bolsas del papel.', 885, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1688, 6, 'C170204', 'Servicios de apoyo a la fabricación de papel y cartón ondulado y de envases de papel y cartón a cambio de una retribución o por contrato.', 885, true);
