INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1690, 6, 'C170912', 'Fabricación de artículos de uso domésticos vasos, platos y bandejas, bandejas para guardar huevos y otros productos para envasado, de papel o cartón moldeado.', 886, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1691, 6, 'C170913', 'Elaboración de bobinas, carretes, tapas, etcétera, de papel o cartón.', 886, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1692, 6, 'C170914', 'Elaboración de papel para empapelar y cubrimientos similares para pared, incluido papel de empapelar textil y recubierto de vinilo, revestimiento para vidrios.', 886, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1693, 6, 'C170915', 'Elaboración de prendas y complementos de vestir de papel o guata de celulosa.', 886, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1694, 6, 'C170921', 'Fabricación de papel para impresora de computadora; papel para imprimir y escribir u otros usos gráficos listo para usar, cortado o perforado, rayado, etcétera (papel Bond, etiqueta, couché).', 887, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1695, 6, 'C170922', 'Elaboración de papel de esténcil, autocopia y otros papeles para copiar o transferir, listo para usar.', 887, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1696, 6, 'C170923', 'Fabricación de papel engomado o adhesivo listo para usar (cintas o rollos), elaboración de sobres, aerogramas, cartas y tarjetas.', 887, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1697, 6, 'C170924', 'Fabricación de registros, libros de contabilidad, cuadernos y artículos de papelería similares de uso educativo o comercial, cuando la información impresa no constituya su característica principal.', 887, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1698, 6, 'C170925', 'Fabricación de cajas, bolsas (fundas), carpetas y juegos de escritorio que contengan una variedad de artículos de papelería, recados de escribir que contienen papel para correspondencia, esquelas o tarjetas postales en blanco, etcétera.', 887, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1699, 6, 'C170929', 'Fabricación de otros artículos de papel o cartón: etiquetas impresas o sin imprimir, artículos de fantasía de papel, artículos promocionales y de regalo de papel, papel y cartón filtro, cuerdas y cordajes de papel, papel para cigarrillo, papel regalo, etcétera.', 887, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1700, 6, 'C170930', 'Servicios de apoyo a la fabricación de otros artículos del papel y cartón a cambio de una retribución o por contrato.', 888, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1701, 6, 'C181101', 'Actividades de impresión de periódicos, revistas y otras publicaciones periódicas.', 889, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1702, 6, 'C181102', 'Actividades de impresión de libros, diccionarios, enciclopedias y folletos, manuscritos musicales y partitura, mapas, atlas, carteles, etcétera; mediante impresión por Offset, fotograbación, impresión flexográfica e impresión en otros tipos de prensa, maquinas autocopistas, impresoras estampadoras, etcétera, incluida la impresión rápida.', 889, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1703, 6, 'C181103', 'Actividades de impresión de sellos de correo, estampillas y timbres fiscales, documentos de títulos, boletos de entradas a espectáculos, cheques y otros valores o documentos de garantía y de seguridad, mediante impresión por Offset, fotograbación, impresión flexográfica e impresión en otros tipos de prensa, maquinas autocopistas, impresoras estampadoras, etcétera, incluida la impresión rápida.', 889, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1704, 6, 'C181104', 'ACTIVIDADES DE IMPRESIÓN DE PÓSTERS GIGANTOGRAFÍAS CATÁLOGOS DE PUBLICIDAD PROSPECTOS Y OTROS IMPRESOS PUBLICITARIOS CALENDARIOS FORMULARIOS COMERCIALES DIRECTORIOS Y OTROS MATERIALES IMPRESOS DE USO COMERCIAL PAPEL DE CORRESPONDENCIA ÁLBUMES AGENDAS PERSONALES DIARIOS TARJETAS DE INVITACIÓN DE VISITA DE PRESENTACIÓN Y OTROS MATERIALES IMPRESOS MEDIANTE IMPRESIÓN POR OFFSET FOTOGRABACIÓN IMPRESIÓN FLEXOGRÁFICA E IMPRESIÓN EN OTROS TIPOS DE PRENSA MAQUINAS AUTOCOPISTAS IMPRESORAS ESTAMPADORAS ETCÉTERA INCLUIDA LA IMPRESIÓN RÁPIDA', 889, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1705, 6, 'C181105', 'Actividades de impresión directa en textiles, plásticos, vidrio, metal, madera y cerámica (excepto serigrafía sobre textiles o prendas de vestir).', 889, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1706, 6, 'C181106', 'Actividades de Impresión en etiquetas o marbetes (por procedimientos litográficos, de rotograbado, flexográficos, u otros).', 889, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1707, 6, 'C181201', 'Actividades de encuadernación de hojas impresas para confeccionar libros, folletos, revistas, catálogos etcétera, mediante el colado, cortado, ensamblado, engomado, compaginado, hilvanado (cosido), encuadernado con adhesivo, recortado, estampado en oro, encuadernación espiral, etcétera.', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1708, 6, 'C181202', 'reparación de placas, planchas y tintes para el estampado y la impresión e impresión en relieve (incluidas planchas de fotopolímeros), preparación de la composición de imágenes y placas para imprentas tipográficas y de Offset. Composición tipografía, fotocomposición, la incorporación de datos antes de la impresión, incluso mediante el escaneo y reconocimiento óptico de caracteres, compaginación electrónica y grabado de cilindros para rotograbado.', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1709, 6, 'C181203', 'Actividades de diseño de productos impresos por ejemplo bocetos, diagramas, patrones, croquis, maquetas, etcétera, producción de pruebas.', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1710, 6, 'C181204', 'Actividades de producción de obras artísticas incluso piedras litográficas y planchas de madera preparadas.', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1711, 6, 'C181205', 'Actividades de producción de productos de reprografía (copiadora).', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1712, 6, 'C181206', 'Actividades de servicios combinados de impresión de texto e imágenes.', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1713, 6, 'C181207', 'Actividades graficas, como el estampado en hueco y estampado a troquel, impresión de libros Braille, troquelado y perforado, estampado en relieve, barnizado y laminado, alzado, encartaciôn y plegado.', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1714, 6, 'C181209', 'Otros actividades de servicios relacionados con la impresión: servicios de preparación de datos digitales, etcétera.', 890, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1715, 6, 'C182001', 'Actividades de reproducción a partir de copias matrices (originales) de: discos gramofónicos, discos compactos y cintas con música u otras grabaciones de sonido.', 891, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1716, 6, 'C182002', 'Actividades de reproducción de copias matrices (originales) de discos, discos compactos, cintas con películas y otras grabaciones de video.', 891, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1717, 6, 'C182003', 'Actividades de reproducción a partir de copias matrices de programas informáticos y datos en discos.', 891, true);
