INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1719, 6, 'C191002', 'Aglomeración de coque.', 892, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1720, 6, 'C191003', 'Servicios de apoyo a la fabricación de productos de horno de coque a cambio de una retribución o por contrato.', 892, true);
