INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1722, 6, 'C192002', 'Fabricación de aceites o grasas lubricantes a base de petróleo, incluido los fabricados a partir de residuos del petróleo.', 893, true);
