INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1724, 6, 'C192004', 'Fabricación de briquetas de carbón de piedra y lignito.', 893, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1725, 6, 'C192005', 'Fabricación de biocombustibles, es decir la mezcla de alcoholes con petróleo por ejemplo: Gasohol.', 893, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1726, 6, 'C192006', 'Servicios de apoyo a la fabricación de productos de la refinación del petróleo a cambio de una retribución o por contrato.', 893, true);
