INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1729, 6, 'C201112', 'Fabricación de álcalis, lejías y otras bases inorgánicas excepto amoníaco.', 894, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1730, 6, 'C201113', 'Elaboración de elementos químicos (excepto gases industriales y metales básicos).', 894, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (1731, 6, 'C201114', 'Fabricación de ácidos inorgánicos excepto acido nítrico.', 894, true);
