INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2300, 6, 'E370000', '); vaciado y limpieza de pozos negros y fosas sépticas, fosos y pozos de alcantarillados; mantenimiento de inodoros de acción química; tratamiento de aguas residuales (incluidas aguas residuales humanas e industriales, agua de piscinas, etcétera) mediante procesos físicos, químicos y biológicos como los de dilución, cribado, filtración, sedimentación, etcétera; mantenimiento y limpieza de cloacas y alcantarillas, incluido el desatasco de cloacas.', 1037, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2301, 6, 'E381100', ' en una zona delimitada: residuos de hogares y empresas por medio de contenedores; desechos recuperables mezclados de materiales reciclables; aceites y grasas usados en la cocina; desperdicios colocados en lugares públicos; desechos de actividades provenientes de la construcción y demolición, recolección y remoción de escombros; desechos producidos por fábricas textiles. Incluye la gestión de estaciones de transferencia de desechos no peligrosos.', 1038, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2302, 6, 'E381200', ', corrosivas o infecciosas y otras substancias y preparados nocivos perjudiciales para la salud humana y el medio ambiente como: aceites usados de buques o garajes, residuos biológicos peligrosos, pilas y baterías usadas; La identificación, tratamiento, embalado y etiquetado de los desechos para su transporte. Se incluyen las siguientes actividades de recolección de desechos peligrosos y gestión de estaciones de expedición de desechos peligrosos.', 1039, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2303, 6, 'E382101', 'Actividades de operación de rellenos sanitarios para la eliminación de desechos no peligrosos; eliminación de desechos no peligrosos mediante combustión o incineración o por otros métodos, con o sin producción resultante de electricidad o vapor, combustibles sustitutivos, biogás, cenizas u otros subproductos para su utilización posterior, etcétera.', 1040, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2304, 6, 'E382102', 'Actividades de tratamiento de desechos orgánicos para su transformación. Incluye la producción de compost con desechos orgánicos.', 1040, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2305, 6, 'E382200', 'ligrosos, remoción de productos usados como refrigeradores, con objeto de eliminar los desechos peligrosos; tratamiento, remoción y almacenamiento de desechos nucleares radiactivos, incluido el tratamiento y eliminación de desechos radiactivos de transición, es decir que se desintegran durante el período de transporte, procedentes de hospitales, encapsulación, preparación y otras formas de tratamiento de desechos nucleares para su almacenamiento.', 1041, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2306, 6, 'E383001', 'avadoras usadas, bicicletas usadas, etcétera, para su posterior clasificación y separación; Desguace de automóviles, buques, computadoras, aparatos de televisión y otros equipos para la recuperación de materiales; Reducción mecánica de grandes volúmenes de metal, como vagones de ferrocarril; Trituración de desechos de metal, vehículos desechados, etcétera; Otros métodos de tratamiento mecánico, como el corte y el prensado para reducir el volumen.', 1042, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2307, 6, 'E383002', 'pieza, fusión, trituración) de desechos de plástico o caucho para convertirlos en gránulos; Trituración, limpieza y clasificación de desechos de vidrio; Trituración, limpieza y clasificación de otros desechos, como los de demoliciones para obtener materias primas secundarias; Procesamiento de aceites y grasas de cocina y de otros desechos y sustancias residuales de productos alimenticios, bebidas y tabaco para obtener materias primas secundarias.', 1042, true);
