INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2309, 6, 'E390002', 'stalaciones o terrenos industriales, incluidos los nucleares; Descontaminación y limpieza de aguas superficiales tras su contaminación accidental; por ejemplo, mediante la recogida de los contaminantes o la aplicación de sustancias químicas; Limpieza de derrames de petróleo y otras formas de contaminación en tierra, aguas superficiales, mares y océanos, incluidas zonas costeras; Eliminación de asbesto, pintura de plomo y otros materiales tóxicos.', 1043, true);
