INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2573, 6, 'H522101', 'elacionadas con el transporte terrestre de pasajeros, animales o carga: explotación de terminales, estaciones ferroviarias, de autobuses, de manipulación de mercancías; Operación de infraestructura de transporte ferroviario su reparación y mantenimiento (limpieza exterior de las unidades, mantenimiento de vías y de equipos, instalación y mantenimiento electromecánico de maquinaria y conducción de líneas), operaciones de cambio de vías o de agujas', 1139, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2574, 6, 'H522102', 'Actividades relacionadas con administración y operaciones de servicios de: carreteras, puentes, túneles, aparcamientos o garajes, aparcamientos para bicicletas.', 1139, true);
