INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2578, 6, 'H522301', 'Actividades relacionadas con el transporte aéreo de pasajeros, animales o carga: explotación de instalaciones terminales, como terminales aéreas, etc. Actividades aeroportuarias y de control de tráfico aéreo. Actividades de servicio en tierra realizadas en aeropuertos, etcétera.', 1141, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2579, 6, 'H522302', 'Servicios de prevención y extinción de incendios en los aeropuertos.', 1141, true);
