INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2581, 6, 'H522901', 'Servicios transitorios de organización o coordinación de operaciones de transporte y flete por tierra, mar y aire.', 1143, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2582, 6, 'H522902', 'ades logísticas: planificación, diseño y apoyo de operaciones de transporte, almacenamiento y distribución; contratación de espacio en buques y aeronaves, organización de envíos de grupo e individuales (incluidas la recogida y entrega de mercancías y la agrupación de envíos); Manipulación de mercancías, como: el embalaje temporal con la exclusiva finalidad de proteger las mercancías durante el tránsito, desembalaje, muestreo y pesaje de la carga.', 1143, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2583, 6, 'H522903', 'Actividades de agentes de aduanas; emisión y tramitación de documentos de transporte y conocimientos de embarque.', 1143, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2584, 6, 'H531000', 'Servicios de recolección de correspondencia y paquetes depositados en buzones públicos o en oficinas de correos, Incluye la distribución y entrega de correspondencia y paquetes. La actividad puede realizarse en uno o varios medios de transporte propios (transporte privado) o de transporte público.', 1144, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2585, 6, 'H532000', 'cios de recolección, clasificación, transporte y entrega (nacional o internacional) de correspondencia ordinaria y paquetes (que cumplan determinadas especificaciones) por parte de empresas no sujetas a la obligación de servicio universal. La actividad puede realizarse en uno o varios medios de transporte propios (transporte privado) o de transporte público. Incluye la distribución y entrega de correspondencia y paquetes y la entrega a domicilio.', 1145, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2586, 6, 'I551001', 'Servicios de alojamiento prestados por hoteles, hoteles de suites, apart hoteles, complejos turísticos, hosterías.', 1146, true);
