INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2590, 6, 'I559001', 'Servicio de residencias de estudiantes, dormitorios escolares, albergues para trabajadores, casas de huéspedes e internados.', 1148, true);
