INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2592, 6, 'I561001', 'Restaurantes, cevicherías, picanterías, cafeterías, etcétera, incluido comida para llevar.', 1149, true);
