INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2599, 6, 'I563001', 'Actividades de preparación y servicio de bebidas para su consumo inmediato en: bares, tabernas, coctelerías, discotecas (con suministro predominante de bebidas) cervecerías y pubs.', 1152, true);
