INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2615, 6, 'J592002', 'La publicación, lanzamiento, promoción y distribución de grabaciones de sonido para comerciantes mayoristas, minoristas o directamente para el público.', 1162, true);
