INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2617, 6, 'J592004', 'Actividades de bandas sonoras de películas cinematográficas, grabaciones de sonido para programas de televisión, etcétera.', 1162, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2618, 6, 'J592005', 'ición de música, es decir, actividades de: adquisición y registro de los derechos de autor de composiciones musicales, promoción, autorización y utilización de esas composiciones en grabaciones, en la radio, en la televisión, en películas, en interpretaciones en vivo, en medios impresos y en otros medios, distribución de grabaciones de sonido a mayoristas o minoristas o directamente al público, incluye la edición de libros de música y partituras.', 1162, true);
