INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2621, 6, 'J602001', 'ACTIVIDADES DE CREACIÓN DEL PROGRAMA COMPLETO DE UNA CADENA DE TELEVISIÓN PARA UN CANAL DESDE LA COMPRA DE LOS COMPONENTES DEL PROGRAMA PELÍCULAS DOCUMENTALES ETCÉTERA HASTA LA PRODUCCIÓN PROPIA DE LOS COMPONENTES DEL PROGRAMA AUTO PRODUCIDOS NOTICIAS LOCALES REPORTAJES EN VIVO O UNA COMBINACIÓN DE LAS DOS OPCIONES EL PROGRAMA COMPLETO DE TELEVISIÓN PUEDE SER EMITIDO POR LAS UNIDADES DE PRODUCCIÓN O BIEN PRODUCIRSE PARA SU TRANSMISIÓN POR TERCEROS DISTRIBUIDORES COMO COMPAÑÍAS DE EMISIÓN POR CABLE O PROVEEDORES DE TELEVISIÓN POR SATÉLITE INCLUYE LA PROGRAMACIÓN DE CANALES DE VIDEO A LA CARTA', 1164, true);
