INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2629, 6, 'J612003', 'Actividades de suministro de acceso a Internet por los operadores de la infraestructura de telecomunicaciones inalámbricas.', 1166, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2630, 6, 'J613001', 'Actividades de operación, mantenimiento o facilitación del acceso a servicios de transmisión de voz, datos, texto, sonido y vídeo utilizando una infraestructura de telecomunicaciones por satélite, actividades de suministro de acceso a Internet por el operador de la infraestructura de telecomunicaciones por satélite.', 1167, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2631, 6, 'J613002', 'Actividades de transmisión a los consumidores por sistemas de comunicación directa por satélite de programas visuales, sonoros o de texto recibidos de redes de cable o estaciones de televisión o cadenas de radio locales. (Las unidades clasificadas en esa clase no producen por lo general material de programación).', 1167, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2632, 6, 'J619001', 'Suministro de aplicaciones especializadas de telecomunicaciones, como detección por satélite, telemetría de comunicaciones y utilización de estaciones de radar.', 1168, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2633, 6, 'J619002', 'Operación de estaciones terminales de comunicaciones por satélite e instalaciones conexas operacionalmente conectadas con uno o varios sistemas de comunicaciones terrestres y capaces de transmitir o recibir telecomunicaciones por satélite.', 1168, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2634, 6, 'J619003', 'Suministro de acceso a Internet por redes que no posee ni controla el proveedor de servicios de Internet, como el acceso telefónico a Internet, etc.', 1168, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2635, 6, 'J619004', 'Actividades de reventa de servicios de telecomunicaciones (suministro de servicios telefónicos y de Internet en instalaciones abiertas al público: cabinas telefónicas y cibercafés.)', 1168, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2636, 6, 'J619005', 'Suministro de servicios de telecomunicaciones por las conexiones de telecomunicaciones existentes: suministro de servicios de telefonía por Internet (VoIP: Voice over Internet Protocol).', 1168, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2637, 6, 'J619006', 'Actividades de gestión y consultoría para la transmisión de datos.', 1168, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2638, 6, 'J619009', 'Otras actividades de telecomunicaciones.', 1168, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2639, 6, 'J620101', 'Actividades de diseño de la estructura y el contenido de los elementos siguientes (y/o escritura del código informático necesario para su creación y aplicación): programas de sistemas operativos (incluidas actualizaciones y parches de corrección), aplicaciones informáticas (incluidas actualizaciones y parches de corrección), bases de datos y páginas web.', 1169, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2640, 6, 'J620102', 'Adaptación de programas informáticos a las necesidades de los clientes, es decir, modificación y configuración de una aplicación existente para que pueda funcionar adecuadamente con los sistemas de información de que dispone el cliente.', 1169, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2641, 6, 'J620210', 'Actividades de planificación y diseño de sistemas informáticos que integran equipo y programas informáticos y tecnología de las comunicaciones.', 1170, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2642, 6, 'J620220', 'Servicios de gestión y manejo in situ de sistemas informáticos y/o instalaciones de procesamiento de datos de los clientes, y servicios de apoyo conexos.', 1171, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2643, 6, 'J620901', 'Actividades relacionadas a la informática como: recuperación en casos de desastre informático, instalación de programas informáticos.', 1172, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2644, 6, 'J620902', 'Actividades de instalación (montaje) de computadoras personales.', 1172, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2645, 6, 'J631101', 'Suministro de infraestructura para servicios de hospedaje, servicios de procesamiento de datos y actividades conexas. Incluye actividades especializadas de hospedaje, como: hospedaje de sitios web, aplicaciones, servicios de transmisión de secuencias de vídeo por Internet.', 1173, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2646, 6, 'J631102', 'Actividades de procesamiento y suministro de servicio de registro de datos: elaboración completa de datos facilitados por los clientes, generación de informes especializados a partir de datos facilitados por los clientes.', 1173, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2647, 6, 'J631103', 'Servicios de aplicaciones.', 1173, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2648, 6, 'J631104', 'Suministro a los clientes de acceso en tiempo compartido a servicios centrales.', 1173, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2649, 6, 'J631200', 'Operación de sitios web que funcionan como portales de Internet, como los sitios de medios de difusión que proporcionan contenidos que se actualizan periódicamente y los que utilizan un motor de búsqueda para generar y mantener amplias bases de datos de direcciones de Internet y de contenidos en un formato que facilite la búsqueda.', 1174, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2650, 6, 'J639100', 'Actividades de consorcios y agencias de noticias que suministran noticias, fotografías y artículos periodísticos a los medios de difusión.', 1175, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2651, 6, 'J639900', 'Otras actividades de servicios de información n.c.p.: servicios de información telefónica, búsqueda de información a cambio de una retribución o por contrato, selección de noticias, de recortes de prensa, etcétera.', 1176, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2652, 6, 'K641100', 'Actividades de emisión y administración de la moneda nacional; supervisión y control de la masa monetaria; recepción de depósitos para operaciones de compensación entre instituciones financieras; supervisión de las operaciones bancarias; mantenimiento de las reservas nacionales de divisas; función de banco del gobierno. Las actividades de los bancos centrales pueden variar por razones institucionales.', 1177, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2653, 6, 'K641901', 'Actividades de recepción de depósitos y/o similares cercanos de depósitos y la concesión de créditos o préstamos de fondos. La concesión de crédito puede adoptar diversas formas, como préstamos, hipotecas, transacciones con tarjetas de crédito, etc. Esas actividades son realizadas por bancos diferentes del Banco Central.', 1178, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2654, 6, 'K641902', 'Actividades de recepción de depósitos y/o similares cercanos de depósitos y la concesión de créditos o préstamos de fondos. La concesión de crédito puede adoptar diversas formas, como préstamos, hipotecas, transacciones con tarjetas de crédito, etc. Esas actividades son realizadas en general por instituciones monetarias diferentes de los bancos centrales, como: cajas de ahorros, cooperativas de crédito y actividades de giro postal.', 1178, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2655, 6, 'K641903', 'similares cercanos de depósitos y la concesión de créditos o préstamos de fondos. La concesión de crédito puede adoptar diversas formas, como préstamos, hipotecas, transacciones con tarjetas de crédito, etc. Esas actividades son realizadas en general por instituciones monetarias diferentes de los bancos centrales, como; Actividades de concesión de crédito para compra de vivienda de instituciones especializadas que reciben depósitos (mutualistas).', 1178, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2656, 6, 'K642000', 'Actividades de sociedades de cartera, es decir, unidades tenedoras de activos de un grupo de empresas filiales (con participación de control en su capital social) y cuya actividad principal consiste en la propiedad del grupo. Las sociedades de cartera clasificadas en esta clase no suministran ningún otro servicio a las empresas participadas, es decir, no administran ni gestionan otras unidades.', 1179, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2657, 6, 'K643000', 'dendos y otras rentas de la propiedad, pero tienen pocos empleados y no obtienen ingresos por concepto de venta de servicios. Se incluyen las siguientes actividades: fondos de inversión de participación abierta; fondos de inversión cerrados; fideicomisos, legados o cuentas de agencia, administrados en nombre de los beneficiarios en virtud de un contrato de fiducia, un testamento o un contrato de representación; sociedades de inversión mobiliaria.', 1180, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2658, 6, 'K649100', 'Actividades de arrendamiento que cubre aproximadamente toda la vida útil prevista de un activo y en el que el arrendatario adquiere prácticamente todos los derechos de usufructo y asume todos los riesgos relacionados con la propiedad del activo, que puede o no ser objeto de traspaso. Esa modalidad de arrendamiento cubre la totalidad o la práctica totalidad de los costos, incluidos intereses.', 1181, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2659, 6, 'K649201', 'Actividades de otorgamiento de crédito de instituciones dedicadas a la intermediación monetaria en las que el crédito puede adoptar diferentes formas como: préstamos, hipotecas, tarjetas de crédito, etcétera. Proporcionando los servicios de: financiamiento para comercio internacional, provisión de financiamiento a largo plazo para la industria a través de bancos industriales, concesión de crédito a los consumidores.', 1182, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2660, 6, 'K649202', 'Actividades de préstamos fuera del sistema bancario, otorgamiento de créditos para vivienda por instituciones especializadas que no reciben depósitos, se incluyen actividades realizadas por las casas de empeño y montes de piedad.', 1182, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2661, 6, 'K649901', 'Otras actividades de servicios financieros consistentes principalmente en modalidades de distribución de fondos distintas de la concesión de préstamos: actividades de factorización, suscripción de permutas financieras, opciones y otros instrumentos de cobertura y actividades de compañías de liquidación por adelantado.', 1183, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2662, 6, 'K649902', 'Actividades de inversión por cuenta propia, como las de compañías de capital riesgo, clubes de inversión, etcétera.', 1183, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2663, 6, 'K651100', 'Concertación de contratos de anualidades y pólizas de seguros de vida, seguros de invalidez y seguros de doble indemnización (tengan o no un componente importante de ahorro).', 1184, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2664, 6, 'K651201', 'Suministros de servicios de seguros distintos de los seguros de vida: seguros de accidentes y contra incendios, seguros médicos, seguros de viajes, seguros de cosas, seguros de transporte por carretera, marítimo y aéreo, seguros contra pérdidas pecuniarias y de responsabilidad civil.', 1185, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2665, 6, 'K651202', 'Servicios de seguro de medicina pre pagada.', 1185, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2666, 6, 'K652000', 'Actividades de asunción de la totalidad o una parte de los riesgos de pólizas de seguros existentes emitidas originariamente por otras compañías de seguros.', 1186, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2667, 6, 'K653000', 'ACTIVIDADES DE ENTIDADES JURÍDICAS ES DECIR DE FONDOS PLANES YO PROGRAMAS ORGANIZADAS PARA PROPORCIONAR PRESTACIONES DE JUBILACIÓN EXCLUSIVAMENTE PARA LOS EMPLEADOS O MIEMBROS DE LA ENTIDAD PATROCINADORA ABARCA PLANES DE PENSIONES CON PRESTACIONES DEFINIDAS Y PLANES INDIVIDUALES EN LOS QUE LAS PRESTACIONES DEPENDEN DE LAS CONTRIBUCIONES DEL AFILIADO SE INCLUYEN LAS SIGUIENTES ACTIVIDADES PLANES DE PRESTACIONES SOCIALES PARA LOS EMPLEADOS FONDOS Y PLANES DE PENSIONES PLANES DE JUBILACIÓN', 1187, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2668, 6, 'K661100', 'Gestión y supervisión de los mercados financieros por entidades distintas de las autoridades públicas, como: mercado (bolsas) de contratos de productos básicos, mercado (bolsas) de futuros, mercado (bolsas) de valores, mercados bursátiles, mercado (bolsas) de opciones sobre acciones o sobre productos básicos, etcétera.', 1188, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2669, 6, 'K661201', 'Actividades de oficinas de cambio.', 1189, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2670, 6, 'K661202', 'Operaciones en los mercados financieros por cuenta ajena (por ejemplo, correduría de bolsa) y actividades conexas. Incluye corretaje de contratos de productos básicos y corretaje de valores.', 1189, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2671, 6, 'K661901', 'Actividades auxiliares de las actividades de servicios financieros n.c.p., como: actividades de tramitación y liquidación de transacciones financieras, incluidas las transacciones con tarjetas de crédito.', 1190, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2672, 6, 'K661902', 'Actividades de servicios de asesoramiento en inversiones y corredores hipotecarios.', 1190, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2673, 6, 'K661903', 'Servicios de administración fiduciaria y de custodia a cambio de una retribución o por contrato.', 1190, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2674, 6, 'K662100', 'Actividades de prestación de servicios administrativos relacionados con los seguros, como la tasación y liquidación de reclamaciones. Se incluyen las siguientes actividades: evaluación de las reclamaciones, tasación de solicitudes de indemnización, evaluación del riesgo, evaluación de riesgos y daños, tasación de averías y pérdidas. Incluye la liquidación de solicitudes de indemnización.', 1191, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2675, 6, 'K662200', 'Actividades de agentes y corredores de seguros (intermediarios de seguros) que venden, negocian u ofertan contratos de anualidades y pólizas de seguros y reaseguros.', 1192, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2676, 6, 'K662900', 'Actividades estrechamente relacionadas con seguros y fondos de pensiones (excepto el ajuste de reclamaciones y las actividades de agentes de seguros) administración de salvamentos, servicios actuariales, etcétera.', 1193, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2677, 6, 'K663000', 'Actividades de personas, empresas y otras entidades que gestionan carteras y fondos a cambio de una retribución o por contrato. Se incluyen las siguientes actividades: gestión de fondos de pensiones, gestión de fondos mutuos de inversión y gestión de otros fondos de inversión.', 1194, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2678, 6, 'L681001', 'Compra - venta, alquiler y explotación de bienes inmuebles propios o arrendados, como: edificios de apartamentos y viviendas; edificios no residenciales, incluso salas de exposiciones; instalaciones para almacenaje, centros comerciales y terrenos; incluye el alquiler de casas y apartamentos amueblados o sin amueblar por períodos largos, en general por meses o por años.', 1195, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2679, 6, 'L681002', 'Explotación de campamentos residenciales para casas móviles.', 1195, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2680, 6, 'L681003', 'Promoción de proyectos de construcción (promoción inmobiliaria) para su posterior explotación, es decir, para alquilar espacio en esos edificios.', 1195, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2681, 6, 'L681004', 'Lotización y parcelación de propiedades inmobiliarias en lotes, sin mejora de los terrenos.', 1195, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2682, 6, 'L682001', 'Actividades de agentes y corredores inmobiliarios.', 1196, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2683, 6, 'L682002', 'Intermediación en la compra, venta y alquiler de bienes inmuebles a cambio de una retribución o por contrato.', 1196, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2684, 6, 'L682003', 'Administración de bienes inmuebles a cambio de una retribución o por contrato.', 1196, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2685, 6, 'L682004', 'Servicios de tasación inmobiliaria.', 1196, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2686, 6, 'L682005', 'Actividades de agentes inmobiliarios neutrales que garantizan el cumplimiento de todas las condiciones de una transacción inmobiliaria (plicas inmobiliarias).', 1196, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2687, 6, 'M691001', 'Actividades de representación jurídica de los intereses de una parte contra otra, sea o no ante tribunales u otros órganos judiciales, realizadas por abogados o bajo la supervisión de abogados: asesoramiento y representación en procedimientos civiles, procedimientos penales y en relación con conflictos laborales.', 1197, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2688, 6, 'M691002', 'Actividades de notarios públicos, prestación de asesoramiento en general, preparación de documentos jurídicos: escrituras de constitución, contratos de sociedad y documentos similares para la formación de sociedades, patentes y derechos de autor, escrituras, testamentos, fideicomisos, etcétera.', 1197, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2689, 6, 'M691003', 'Otras actividades de ejecutores judiciales, alguaciles, árbitros, examinadores y mediadores.', 1197, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2690, 6, 'M691009', 'Otras actividades de asesoramiento y representación en procedimientos jurídicos (derecho constitucional, administrativo, militar, etcétera).', 1197, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2691, 6, 'M692001', 'Actividades de registro de las transacciones comerciales de empresas y otras entidades.', 1198, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2692, 6, 'M692002', 'Actividades de preparación o auditoria de las cuentas financieras y examen y certificación de cuentas.', 1198, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2693, 6, 'M692003', 'Actividades de preparación de las declaraciones tributarias de las personas y empresas; asesoramiento y de representación de clientes ante las autoridades tributarias.', 1198, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2694, 6, 'M692009', 'Otras actividades de contabilidad, teneduría de libros y auditoria; consultoría fiscal (procesamiento de nómina, etcétera).', 1198, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2695, 6, 'M701000', 'Supervisión y gestión de otras unidades de la misma compañía o empresa, asumiendo la planificación estratégica, organizativa y la función de toma de decisiones de la compañía o empresa; ejerciendo el control operativo y la gestión de las operaciones corrientes de las otras unidades: oficinas principales, oficinas administrativas centralizadas, sedes, oficinas de distrito, regionales y oficinas subsidiarias de gestión.', 1199, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2696, 6, 'M702001', 'Servicios de asesoramiento, orientación y asistencia operativa a las empresas y a la administración pública en materia de: relaciones públicas y comunicaciones.', 1200, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2697, 6, 'M702002', 'Servicios de asesoramiento, orientación y asistencia operativa a las empresas y a la administración pública en materia de: actividades de cabildeo (grupos de presión (lobbies)).', 1200, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2698, 6, 'M702003', 'Servicios de  asesoramiento, orientación y asistencia operativa a las empresas y a la administración pública en materia de: diseño de métodos o procedimientos contables, programas de contabilidad de costos y procedimientos de control presupuestario.', 1200, true);
