INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2806, 6, 'N782000', 'Suministro de trabajadores para las actividades de los clientes por períodos limitados de tiempo con el fin de reemplazar a empleados de los clientes o suplementar temporalmente su fuerza de trabajo, cuando los trabajadores suministrados son empleados de las propias agencias de empleo temporal. Las unidades clasificadas en esta clase no se encargan de la supervisión directa de sus empleados en los lugares de trabajo de los clientes.', 1227, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2807, 6, 'N783000', ' por lo general a largo plazo o de forma permanente, y las unidades clasificadas en esta clase pueden desempeñar una amplia gama de funciones conexas de gestión de recursos humanos. Las unidades clasificadas aquí constituyen los empleadores oficiales de los empleados en lo que respecta a la nómina, los impuestos y otros aspectos fiscales y de recursos humanos, pero no se encargan de la dirección ni de la supervisión del trabajo de esos empleados.', 1228, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2808, 6, 'N791100', 'Actividades de las agencias de viajes dedicadas principalmente a vender servicios de viajes, de viajes organizados, de transporte y de alojamiento, al por mayor o al por menor, al público en general y a clientes comerciales.', 1229, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2809, 6, 'N791200', 'Actividad de Operadores turísticos que se encargan de la planificación y organización de paquetes de servicios de viajes (tours) para su venta a través de agencias de viajes o por los propios operadores turísticos. Esos viajes organizados (tours) pueden incluir la totalidad o parte de las siguientes características: transporte, alojamiento, comidas, visitas a museos, lugares históricos o culturales, espectáculos teatrales, musicales o deportivos.', 1230, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2810, 6, 'N799001', 'Prestación de otros servicios de reservas relacionados con los viajes: reservas de transporte, hoteles, restaurantes, alquiler de automóviles, entretenimiento y deporte, etcétera.', 1231, true);
