INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2820, 6, 'N802002', 'Actividades de instalación, reparación, reconstrucción y ajuste de dispositivos mecánicos o eléctricos de cierre, cajas de caudales y cajas fuertes. La unidad que lleva a cabo esta actividad puede dedicarse también a la venta de estos dispositivos mecánicos o eléctricos de cierre, cajas de caudales y cajas fuertes.', 1233, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2821, 6, 'N803000', 'Actividades de todo tipo de investigadores privados, independientemente del tipo de cliente y de la finalidad de la investigación, servicios de investigación y de detectives y otras actividades de investigación.', 1234, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2822, 6, 'N811000', 'es de los clientes, como limpieza general de interiores, mantenimiento, eliminación de la basuras, seguridad y vigilancia, envío de correo, recepción, lavandería y servicios conexos, a fin de facilitar el funcionamiento de las instalaciones. Las unidades clasificadas en esta clase proporcionan personal para la realización de estas actividades de apoyo, pero no participan en las actividades principales de los clientes ni son responsables de ellas.', 1235, true);
