INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2892, 6, 'P851011', 'La educación preprimaria o inicial (es el proceso de acompañamiento al desarrollo integral que considera los aspectos cognitivos, afectivo, psicomotriz, social, de identidad, autonomía y pertinencia a la comunidad diseñada principalmente para introducir a los niños y niñas, desde los tres años hasta los cinco años de edad en un entorno educativo de tipo escolar, es decir, servir de puente entre el hogar y el medio escolar).', 1257, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2893, 6, 'P851012', 'Educación preprimaria ó inicial especial, para alumnos con discapacidad.', 1257, true);
