INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2895, 6, 'P851022', 'Educación primaria especial, para alumnos con discapacidad.', 1258, true);
INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (2896, 6, 'P851023', 'Programas de alfabetización para adultos en el nivel primario educativo. La educación puede ser provista en salones de clases o a través de radio, televisión, Internet, correspondencia o en el hogar.', 1258, true);
