INSERT INTO general.actividad_economica (id, id_tipo_actividad, codigo, nombre, id_actividad_padre, activo) VALUES (3043, 6, 'T981000', 'ión, la agricultura, la construcción de viviendas y la confección de prendas de vestir y otros bienes producidos por los hogares para su propia subsistencia. Si los hogares se dedican a la producción de bienes para el mercado, se clasifican en la rama de producción correspondiente a esos bienes. Si se dedican principalmente a la producción de bienes de subsistencia específicos, se clasifican en la rama de producción correspondiente a esos bienes.', 1306, true);
